add_action(
    'wp_enqueue_scripts',
    'bs_account_nav_icons_v4',
    1000
);

function bs_account_nav_icons_v4() {
    if (
        ! function_exists( 'is_account_page' )
        || ! is_account_page()
    ) {
        return;
    }

    $cfg = bs_account_nav_config_v4();
    $css = '';

    foreach ( $cfg['icons'] as $endpoint => $paths ) {
        if ( ! preg_match( '/^[a-z0-9-]+$/', $endpoint ) ) {
            continue;
        }

        $svg =
            '<svg xmlns="http://www.w3.org/2000/svg"'
            . ' viewBox="0 0 24 24"'
            . ' fill="none" stroke="black"'
            . ' stroke-width="1.6"'
            . ' stroke-linecap="round"'
            . ' stroke-linejoin="round">'
            . $paths
            . '</svg>';

        $image = 'url("data:image/svg+xml,'
            . rawurlencode( $svg )
            . '")';

        $targets = array(
            /* منوی دسکتاپ */
            'body.woocommerce-account'
            . ' nav.woocommerce-MyAccount-navigation'
            . ' li.woocommerce-MyAccount-navigation-link--'
            . $endpoint . '>a',

            /* منوی کشویی موبایل */
            'body.woocommerce-account'
            . ' .mobile-dropdown-menu'
            . ' .top_accoun_nav_item'
            . '.woocommerce-MyAccount-navigation-link--'
            . $endpoint . '>a',
        );

        foreach ( $targets as $a ) {
            $css .= $a . '{
                position:relative!important;
                padding-right:44px!important;
            }';

            $css .= $a . '::after{
                content:none!important;
                display:none!important;
            }';

            $css .= $a . '>i{
                display:none!important;
            }';

            $css .= $a . '::before{
                content:""!important;
                display:block!important;
                position:absolute!important;
                right:12px!important;
                left:auto!important;
                top:50%!important;
                bottom:auto!important;
                transform:translateY(-50%)!important;
                width:18px!important;
                height:18px!important;
                margin:0!important;
                padding:0!important;
                border:0!important;
                border-radius:0!important;
                font-size:0!important;
                line-height:0!important;
                opacity:1!important;
                background:currentColor!important;
                pointer-events:none;
                -webkit-mask-image:' . $image . '!important;
                mask-image:' . $image . '!important;
                -webkit-mask-size:contain!important;
                mask-size:contain!important;
                -webkit-mask-repeat:no-repeat!important;
                mask-repeat:no-repeat!important;
                -webkit-mask-position:center!important;
                mask-position:center!important;
            }';
        }
    }


    // Monthly report search: keep suggestions above the following account card.
    if (function_exists('is_wc_endpoint_url') && is_wc_endpoint_url('study-hours')) {
        $css .= '
        .bs-app #bsc-monthly.bsm{position:relative!important;overflow:visible!important}
        .bs-app #bsc-monthly.bsm:focus-within{z-index:30!important}
        .bs-app #bsc-monthly .bsm-filters{position:relative!important;overflow:visible!important;z-index:2}
        .bs-app #bsc-monthly .bsm-picker{position:relative!important;overflow:visible!important;z-index:3!important}
        .bs-app #bsc-monthly .bsm-results{z-index:40!important;max-height:min(240px,50vh);overflow-y:auto!important;overscroll-behavior:contain}
        ';
    }

    wp_register_style(
        'bs-account-nav-v4',
        false,
        array(),
        '4.0'
    );

    wp_enqueue_style( 'bs-account-nav-v4' );

    wp_add_inline_style(
        'bs-account-nav-v4',
        $css
    );
}


/* ساده‌سازی منوی مدیرکل؛ منوی دانش‌آموزان بدون تغییر */
add_filter('woocommerce_account_menu_items', function ($items) {
    if (!current_user_can('manage_options')) {
        return $items;
    }
    unset($items['wishlist'], $items['bse-results'], $items['quiz-results']);
    return $items;
}, 100050);
